-- Why the length of your exam tells you nothing
INSERT INTO nclex_tutor_library_notes
  (note_id, tutor_id, title, subtitle, body, tags, pillars,
   is_published, visibility_mode)
VALUES (
  '55000000-0000-4000-8000-000000000001', '4ed777d7-e4f7-403b-88f4-63ce5432d65e',
  'Why the length of your exam tells you nothing',
  'How computerised adaptive testing actually decides',
  $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "The NCLEX-RN is a "}, {"type": "text", "text": "computerised adaptive test", "marks": [{"type": "bold"}]}, {"type": "text", "text": ". There is no 70% pass mark. The computer asks one question, re-estimates your ability from your answer, then picks the next question to sit as close to that estimate as it can."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Three consequences candidates lose sleep over"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "1. About half your questions will feel hard"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "That is the machine working correctly. It hunts for the level where you get roughly half right, because that is where it learns the most about you. An exam that feels easy the whole way through is the more worrying sign."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "2. Shutting off at 85 questions means nothing on its own"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The exam ends when the computer is "}, {"type": "text", "text": "95% confident", "marks": [{"type": "bold"}]}, {"type": "text", "text": " you are either above or below the passing standard. It can reach that confidence at 85 questions or at 150. Candidates pass at 85; candidates fail at 85."}]}, {"type": "callout", "attrs": {"tone": "warning"}, "content": [{"type": "text", "text": "You cannot read your result from the question count. The friend in your WhatsApp group who says \"it stopped at 85, you passed\" is guessing."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "3. The last question is not the deciding one"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Your ability estimate is built from your whole performance. Getting the final question wrong does not undo the exam."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The three ways your test ends"}]}, {"type": "lab_values", "attrs": {"title": "How the exam stops", "columns": [{"label": "Rule"}, {"label": "What happens"}, {"label": "Pass condition"}], "rows": [["Confidence rule", "95% certain you are above or below the standard", "Estimate sits above the standard"], ["Maximum length", "You reach the maximum number of questions", "Final estimate above the standard"], ["Run-out-of-time", "The clock expires before either rule triggers", "Your last 60 answers hold above the standard"]]}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "What this changes about how you study"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Because the engine adapts, you cannot pass by memorising a bank of questions. It will keep climbing until it finds your ceiling. What moves your ceiling is reasoning — knowing why you assess before you intervene, and why airway beats pain every time."}]}, {"type": "callout", "attrs": {"tone": "tip"}, "content": [{"type": "text", "text": "Practise in untimed learning mode early in the programme, and switch to timed mocks in the last three weeks. Speed without reasoning just gets you to the wrong answer faster."}]}]}$body$::jsonb,
  ARRAY['cat', 'exam-strategy', 'high-yield']::text[],
  ARRAY['Management of Care']::text[],
  TRUE, 'TUTOR_WIDE'
)
ON CONFLICT (note_id) DO UPDATE SET
  title = EXCLUDED.title, subtitle = EXCLUDED.subtitle,
  body = EXCLUDED.body, tags = EXCLUDED.tags,
  pillars = EXCLUDED.pillars, is_published = TRUE,
  version_id = gen_random_uuid(), updated_at = NOW();

-- ABC priority hierarchy
UPDATE nclex_tutor_library_notes SET
  title = 'ABC priority hierarchy',
  subtitle = 'Airway, Breathing, Circulation — and when it does not apply',
  body = $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "When a question asks which client to see "}, {"type": "text", "text": "first", "marks": [{"type": "bold"}]}, {"type": "text", "text": ", which action takes priority, or who is most at risk, ABC decides most of them."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The order"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Airway"}, {"type": "text", "text": " — is it open and protected? Stridor, choking, swelling, unresponsive with no gag reflex."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Breathing"}, {"type": "text", "text": " — is air actually moving? Rate, effort, saturation, absent breath sounds, silent chest in asthma."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Circulation"}, {"type": "text", "text": " — is blood reaching tissue? Bleeding, blood pressure, pulses, capillary refill, arrhythmia."}]}]}]}, {"type": "callout", "attrs": {"tone": "memory"}, "content": [{"type": "text", "text": "A patient can survive minutes without circulation and seconds without an airway. Time-to-death is the whole logic of the ordering."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The traps"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Trap 1 — a normal-sounding airway problem hidden in ordinary words"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "\"Hoarse voice after a thyroidectomy\", \"drooling and won't lie flat\", \"restless\" — restlessness is early hypoxia, not anxiety. Restless plus a respiratory history outranks a client in severe pain."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Trap 2 — ABC only ranks the unstable"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "If every option is stable, ABC gives you nothing and the question is really about Maslow, safety, or timing. Check that at least one option describes an actual physiological threat before you reach for ABC."}]}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "Exception: in a cardiac arrest the order is C-A-B — compressions first. The NCLEX tests this directly."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Worked example"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Which client should the nurse assess first?", "marks": [{"type": "bold"}]}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A client 2 days post-op reporting pain of 8/10"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A client with a new tracheostomy who is coughing up thick secretions"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A client with a haemoglobin of 8.1 g/dL awaiting transfusion"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A client with a blood pressure of 88/56 who is alert"}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The tracheostomy client. Thick secretions in a new trach is an airway at risk of occlusion. The hypotensive client is circulation — real, but one level down, and the client is alert. Pain never outranks ABC."}]}]}$body$::jsonb,
  tags = ARRAY['priority', 'abc', 'strategy']::text[],
  pillars = ARRAY['Management of Care', 'Physiological Adaptation']::text[],
  is_published = TRUE,
  version_id = gen_random_uuid(),
  updated_at = NOW()
WHERE note_id = 'e3eb4c15-3aec-46cd-b0d5-992651f4fe39'
  AND tutor_id = '4ed777d7-e4f7-403b-88f4-63ce5432d65e';

-- Maslow's hierarchy on NCLEX
UPDATE nclex_tutor_library_notes SET
  title = 'Maslow''s hierarchy on NCLEX',
  subtitle = 'When physiological needs beat psychosocial ones — and when they do not',
  body = $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Maslow answers priority questions that ABC cannot, because every option is physiologically stable and the exam wants to know what you value."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The order you apply"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Physiological — airway, fluids, nutrition, elimination, pain, sleep"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Safety — falls, infection, injury, suicide risk, medication error"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Love and belonging — isolation, family, support"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Esteem — dignity, independence, body image"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Self-actualisation — meaning, acceptance, growth"}]}]}]}, {"type": "callout", "attrs": {"tone": "tip"}, "content": [{"type": "text", "text": "Physical need first, then safety, then feelings. If two options are both physiological, drop back to ABC to split them."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Where candidates go wrong"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Assuming psychosocial answers are always wrong"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "They are not. When the question stem is about "}, {"type": "text", "text": "communication", "marks": [{"type": "bold"}]}, {"type": "text", "text": " — a client who has just received a diagnosis, a grieving family, a client refusing treatment — the psychosocial option is usually correct. Maslow ranks competing needs; it does not delete the top of the pyramid."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Forgetting that safety includes psychological safety"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A client expressing suicidal intent is a "}, {"type": "text", "text": "safety", "marks": [{"type": "bold"}]}, {"type": "text", "text": " problem, not an esteem one. It outranks nutrition, sleep and pain."}]}, {"type": "callout", "attrs": {"tone": "warning"}, "content": [{"type": "text", "text": "Read the stem for the word 'first', 'initial', 'priority' or 'most important'. If none of them appear, the question may not be a priority question at all, and Maslow will lead you astray."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Quick discriminator"}]}, {"type": "lab_values", "attrs": {"title": "Which framework does this question want?", "columns": [{"label": "The stem looks like"}, {"label": "Use"}], "rows": [["One client is physiologically unstable", "ABC"], ["All clients stable, needs compete", "Maslow"], ["Who can I give this task to?", "Delegation rules"], ["Client has just been told bad news", "Therapeutic communication"], ["Something in the room could cause harm", "Safety / infection control"]]}}]}$body$::jsonb,
  tags = ARRAY['priority', 'maslow', 'strategy']::text[],
  pillars = ARRAY['Psychosocial Integrity', 'Management of Care']::text[],
  is_published = TRUE,
  version_id = gen_random_uuid(),
  updated_at = NOW()
WHERE note_id = '59c113e5-0fcd-4d04-ad1a-1d91d222a203'
  AND tutor_id = '4ed777d7-e4f7-403b-88f4-63ce5432d65e';

-- Select-all-that-apply strategy
UPDATE nclex_tutor_library_notes SET
  title = 'Select-all-that-apply strategy',
  subtitle = 'Why SATA feels brutal, and the method that fixes it',
  body = $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Select-all-that-apply items are scored on "}, {"type": "text", "text": "partial credit", "marks": [{"type": "bold"}]}, {"type": "text", "text": " in the current test plan — you earn marks for each correct option you select and lose them for wrong selections. That changes the tactics completely."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The method"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Cover the options."}, {"type": "text", "text": " Read the stem and answer it in your own head first."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Treat each option as a separate true/false question."}, {"type": "text", "text": " Not \"is this the best answer\" — \"is this statement true about this client, in this situation?\""}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Say why out loud for each."}, {"type": "text", "text": " If you cannot give a reason, it is a guess, and guesses cost marks under partial credit."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Do not count."}, {"type": "text", "text": " There is no rule that says three are correct. It can be one, it can be all of them."}]}]}]}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "The single most expensive habit in SATA is selecting an option because it is true in general, without checking it is true for THIS client. \"Encourage fluids\" is true for most clients and dangerous in heart failure and renal failure."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The two words that decide most options"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Scan every option for an "}, {"type": "text", "text": "absolute", "marks": [{"type": "bold"}]}, {"type": "text", "text": " — always, never, all, only, every. Nursing is full of exceptions, so absolutes are usually false. Then scan for the "}, {"type": "text", "text": "client-specific", "marks": [{"type": "bold"}]}, {"type": "text", "text": " detail in the stem — age, diagnosis, day post-op, lab value — and re-test each option against it."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Worked example"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A client is admitted with acute pancreatitis. Which nursing actions are appropriate? Select all that apply.", "marks": [{"type": "bold"}]}]}, {"type": "lab_values", "attrs": {"title": "Option-by-option", "columns": [{"label": "Option"}, {"label": "True/false"}, {"label": "Why"}], "rows": [["Maintain NPO status", "TRUE", "Rests the pancreas — the core intervention"], ["Position on the left side, flat", "FALSE", "Sitting up and leaning forward relieves pain"], ["Monitor serum amylase and lipase", "TRUE", "Diagnostic and trend markers"], ["Administer a high-fat diet when eating resumes", "FALSE", "Low fat — fat triggers pancreatic stimulation"], ["Assess for Cullen and Turner signs", "TRUE", "Flank/periumbilical bruising signals haemorrhagic progression"]]}}, {"type": "callout", "attrs": {"tone": "tip"}, "content": [{"type": "text", "text": "Under partial credit, three confident selections beat five hopeful ones. Leave an option unselected if you cannot justify it."}]}]}$body$::jsonb,
  tags = ARRAY['strategy', 'sata', 'high-yield']::text[],
  pillars = ARRAY['Management of Care']::text[],
  is_published = TRUE,
  version_id = gen_random_uuid(),
  updated_at = NOW()
WHERE note_id = '33af9997-2289-4802-be98-9110668ea0db'
  AND tutor_id = '4ed777d7-e4f7-403b-88f4-63ce5432d65e';

-- Delegation: who can do what
INSERT INTO nclex_tutor_library_notes
  (note_id, tutor_id, title, subtitle, body, tags, pillars,
   is_published, visibility_mode)
VALUES (
  '55000000-0000-4000-8000-000000000002', '4ed777d7-e4f7-403b-88f4-63ce5432d65e',
  'Delegation: who can do what',
  'RN, LPN/LVN and UAP scope — the exam''s favourite management question',
  $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Management of Care is the largest single category on the test plan, and delegation is the biggest slice of it. The exam wants one thing: can you protect the tasks that require nursing judgement?"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The rule that answers most items"}]}, {"type": "callout", "attrs": {"tone": "memory"}, "content": [{"type": "text", "text": "The RN keeps ASSESSMENT, TEACHING, EVALUATION, JUDGEMENT and anything involving an UNSTABLE client. Everything delegated must be routine, predictable, and on a stable client."}]}, {"type": "lab_values", "attrs": {"title": "Scope at a glance", "columns": [{"label": "Role"}, {"label": "Can do"}, {"label": "Never"}], "rows": [["RN", "Assessment, care planning, teaching, evaluation, IV push, blood, unstable clients", "—"], ["LPN / LVN", "Stable clients, routine meds, wound care, tracheostomy care, reinforce teaching", "Initial assessment, care plan, IV push, blood, unstable clients"], ["UAP / NA", "ADLs, vitals on stable clients, positioning, feeding, ambulating, intake/output", "Anything requiring judgement, any teaching, any assessment, any medication"]]}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The five rights of delegation"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Right task — routine, standardised, low-risk"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Right circumstance — the client is stable and the outcome predictable"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Right person — within that person's scope and demonstrated competence"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Right direction — clear, specific instruction, including what to report back"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Right supervision — you follow up; delegation never transfers accountability"}]}]}]}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "Accountability does not delegate. If a UAP takes a blood pressure and does not report it, the RN who delegated is answerable."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The traps"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "\"Reinforce\" versus \"teach\""}]}, {"type": "paragraph", "content": [{"type": "text", "text": "An LPN may "}, {"type": "text", "text": "reinforce", "marks": [{"type": "bold"}]}, {"type": "text", "text": " teaching the RN has already given. An LPN may not perform the "}, {"type": "text", "text": "initial", "marks": [{"type": "bold"}]}, {"type": "text", "text": " teaching. Watch for that single word — it flips the answer."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Stable is doing the work in the stem"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A UAP can take vitals — on a stable client. On a client who is 2 hours post-op, or newly on a titrated drip, those vitals are assessment data and belong to the nurse."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Worked example"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Which task is appropriate for the RN to delegate to the UAP?", "marks": [{"type": "bold"}]}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Measuring vital signs on a client admitted 30 minutes ago with chest pain"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Assisting a stable client 3 days post-op to ambulate in the corridor"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Teaching a newly diagnosed diabetic to self-inject insulin"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Assessing a wound that the client reports is now draining"}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Ambulating the stable post-op client. The chest-pain admission is unstable, teaching is never delegated, and assessment stays with the nurse."}]}]}$body$::jsonb,
  ARRAY['delegation', 'scope', 'high-yield']::text[],
  ARRAY['Management of Care']::text[],
  TRUE, 'TUTOR_WIDE'
)
