-- Standard, contact, droplet, airborne
INSERT INTO nclex_tutor_library_notes
  (note_id, tutor_id, title, subtitle, body, tags, pillars,
   is_published, visibility_mode)
VALUES (
  '55000000-0000-4000-8000-000000000003', '4ed777d7-e4f7-403b-88f4-63ce5432d65e',
  'Standard, contact, droplet, airborne',
  'Isolation precautions, and the conditions that trigger each',
  $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Precaution questions are free marks if you know which bucket a condition sits in, and lost marks if you guess from the disease name."}]}, {"type": "lab_values", "attrs": {"title": "The four levels", "columns": [{"label": "Level"}, {"label": "PPE"}, {"label": "Room"}, {"label": "Classic conditions"}], "rows": [["Standard", "Gloves; add gown/mask if splash likely", "Any", "Every client, every time — blood and body fluids"], ["Contact", "Gloves + gown", "Private or cohort", "C. difficile, MRSA, VRE, RSV, scabies, impetigo"], ["Droplet", "Surgical mask within 1–2 metres", "Private or cohort", "Influenza, pertussis, mumps, rubella, meningococcal meningitis, group A strep"], ["Airborne", "N95 respirator (fit-tested)", "Negative pressure, door closed", "Tuberculosis, measles, varicella, disseminated zoster"]]}}, {"type": "callout", "attrs": {"tone": "memory"}, "content": [{"type": "text", "text": "Airborne is My Chicken Has TB — Measles, Chickenpox (varicella), Herpes zoster disseminated, TB."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The traps"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Alcohol gel does not kill C. difficile"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Spore-forming organisms need "}, {"type": "text", "text": "soap and water", "marks": [{"type": "bold"}]}, {"type": "text", "text": " with friction. If the stem says C. diff and an option says alcohol-based rub, that option is wrong."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Varicella and disseminated zoster need airborne AND contact"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The lesions are infectious by contact and the virus is airborne. Localised zoster in an immunocompetent client covered by a dressing needs contact only."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Neutropenic clients are protected, not isolated"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Protective precautions run the other way — the client is at risk from us. No fresh flowers, no raw fruit and vegetables, no visitors with any infection, and a private room with positive-pressure airflow where available."}]}, {"type": "callout", "attrs": {"tone": "warning"}, "content": [{"type": "text", "text": "The order of removal matters and is tested: gloves, goggles, gown, mask — the most contaminated item first, and the mask last because you remove it outside the room."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Room assignment questions"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "When asked to place a new admission, look for the client who can safely share. Two clients with the "}, {"type": "text", "text": "same", "marks": [{"type": "bold"}]}, {"type": "text", "text": " organism may cohort. Never place an immunosuppressed client with anyone infectious, and never place a client with an airborne condition in a shared room at all."}]}]}$body$::jsonb,
  ARRAY['infection-control', 'precautions', 'high-yield']::text[],
  ARRAY['Safety and Infection Control']::text[],
  TRUE, 'TUTOR_WIDE'
)
ON CONFLICT (note_id) DO UPDATE SET
  title = EXCLUDED.title, subtitle = EXCLUDED.subtitle,
  body = EXCLUDED.body, tags = EXCLUDED.tags,
  pillars = EXCLUDED.pillars, is_published = TRUE,
  version_id = gen_random_uuid(), updated_at = NOW();

-- Dosage calculation: the three formulas
INSERT INTO nclex_tutor_library_notes
  (note_id, tutor_id, title, subtitle, body, tags, pillars,
   is_published, visibility_mode)
VALUES (
  '55000000-0000-4000-8000-000000000004', '4ed777d7-e4f7-403b-88f4-63ce5432d65e',
  'Dosage calculation: the three formulas',
  'Everything the exam asks, using three patterns',
  $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Calculation items are the only questions on the exam where you either get it right or you do not — no reasoning to argue about. They are also the easiest marks available, because there are only three patterns."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "1. Tablets and liquids"}]}, {"type": "callout", "attrs": {"tone": "memory"}, "content": [{"type": "text", "text": "Desired over Have, times Quantity.  (D ÷ H) × Q"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Ordered 0.25 mg. Available 125 microgram tablets. Convert first — 0.25 mg = 250 micrograms. (250 ÷ 125) × 1 tablet = "}, {"type": "text", "text": "2 tablets", "marks": [{"type": "bold"}]}, {"type": "text", "text": "."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "2. IV flow rate in mL/hour"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Total volume ÷ total hours. 1000 mL over 8 hours = "}, {"type": "text", "text": "125 mL/hour", "marks": [{"type": "bold"}]}, {"type": "text", "text": "."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "3. IV drip rate in drops/minute"}]}, {"type": "callout", "attrs": {"tone": "memory"}, "content": [{"type": "text", "text": "(Volume × drop factor) ÷ time in minutes"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "1000 mL over 8 hours with a 15 gtt/mL set: (1000 × 15) ÷ 480 = "}, {"type": "text", "text": "31 gtt/min", "marks": [{"type": "bold"}]}, {"type": "text", "text": " (round to whole drops — you cannot give a third of a drop)."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Weight-based doses"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Convert pounds to kilograms first — divide by 2.2. Then multiply by the dose per kilogram, then compare with the safe range if one is given."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A child weighs 44 lb. Order is 15 mg/kg/day in 3 divided doses. 44 ÷ 2.2 = 20 kg. 20 × 15 = 300 mg/day. 300 ÷ 3 = "}, {"type": "text", "text": "100 mg per dose", "marks": [{"type": "bold"}]}, {"type": "text", "text": "."}]}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "If the calculated dose falls outside the safe range, the answer is to HOLD the drug and contact the prescriber — never to give the nearest safe amount on your own."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The four habits that lose marks"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Not converting units before calculating — mg and microgram, kg and lb, mL and L"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Rounding partway through instead of at the end"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ignoring the answer format the question asks for — whole number, one decimal, nearest whole drop"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Typing the unit into the box when only the number is wanted"}]}]}]}, {"type": "callout", "attrs": {"tone": "tip"}, "content": [{"type": "text", "text": "Write the units next to every number as you work. Nearly every wrong answer in this topic is a unit that was never converted."}]}]}$body$::jsonb,
  ARRAY['calculation', 'dosage', 'high-yield']::text[],
  ARRAY['Pharmacological and Parenteral Therapies']::text[],
  TRUE, 'TUTOR_WIDE'
)
ON CONFLICT (note_id) DO UPDATE SET
  title = EXCLUDED.title, subtitle = EXCLUDED.subtitle,
  body = EXCLUDED.body, tags = EXCLUDED.tags,
  pillars = EXCLUDED.pillars, is_published = TRUE,
  version_id = gen_random_uuid(), updated_at = NOW();

-- Heparin vs Warfarin
UPDATE nclex_tutor_library_notes SET
  title = 'Heparin vs Warfarin',
  subtitle = 'Two anticoagulants, two labs, two antidotes',
  body = $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "The exam pairs these two constantly, because confusing their monitoring test or their antidote is a genuine patient-safety error."}]}, {"type": "lab_values", "attrs": {"title": "Side by side", "columns": [{"label": ""}, {"label": "Heparin"}, {"label": "Warfarin"}], "rows": [["Route", "IV or subcutaneous", "Oral"], ["Onset", "Immediate (IV)", "3–5 days"], ["Monitor", "aPTT", "PT / INR"], ["Therapeutic range", "aPTT 1.5–2.5 × control", "INR 2–3 (2.5–3.5 for mechanical valves)"], ["Antidote", "Protamine sulfate", "Vitamin K (phytonadione)"], ["Crosses placenta", "No — anticoagulant of choice in pregnancy", "Yes — teratogenic"]]}}, {"type": "callout", "attrs": {"tone": "memory"}, "content": [{"type": "text", "text": "Heparin has a PTT. Warfarin has a PT. The letters line up: hepa-P-T-T, warfarin-P-T."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Why they overlap in practice"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Warfarin takes days to reach therapeutic effect, so a client is commonly started on both, with heparin stopped once the INR is therapeutic. A question showing both prescribed at once is not an error to report."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The must-knows"}]}, {"type": "drug_card", "attrs": {"name": "Heparin", "drug_class": "Anticoagulant — antithrombin activator", "fields": [{"label": "Monitor", "value": "aPTT, platelet count, signs of bleeding"}, {"label": "Critical adverse effect", "value": "Heparin-induced thrombocytopenia (HIT) — a fall in platelets of 50% or more; stop the heparin immediately"}, {"label": "Antidote", "value": "Protamine sulfate"}, {"label": "Nursing", "value": "Never massage the subcutaneous site; rotate sites; do not aspirate"}]}}, {"type": "drug_card", "attrs": {"name": "Warfarin", "drug_class": "Anticoagulant — vitamin K antagonist", "fields": [{"label": "Monitor", "value": "PT / INR"}, {"label": "Teaching", "value": "Keep vitamin K intake CONSISTENT — not zero. Sudden increases in green leafy vegetables lower the INR"}, {"label": "Antidote", "value": "Vitamin K; fresh frozen plasma if bleeding is active"}, {"label": "Interactions", "value": "Antibiotics, amiodarone, NSAIDs and alcohol all raise bleeding risk"}]}}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "An INR above 5 with any bleeding is an emergency. Hold the dose and contact the prescriber — do not simply document and reassess."}]}]}$body$::jsonb,
  tags = ARRAY['anticoagulant', 'lab', 'high-yield']::text[],
  pillars = ARRAY['Pharmacological and Parenteral Therapies', 'Reduction of Risk Potential']::text[],
  is_published = TRUE,
  version_id = gen_random_uuid(),
  updated_at = NOW()
WHERE note_id = '67f1c58f-a69d-4b4b-9304-393129a820c4'
  AND tutor_id = '4ed777d7-e4f7-403b-88f4-63ce5432d65e';

-- Beta blockers — class overview
UPDATE nclex_tutor_library_notes SET
  title = 'Beta blockers — class overview',
  subtitle = 'The -olol drugs: what they do, and who must not have them',
  body = $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Every drug ending in "}, {"type": "text", "text": "-olol", "marks": [{"type": "bold"}]}, {"type": "text", "text": " is a beta blocker. They slow the heart, reduce contractility and lower blood pressure — which is exactly why they are dangerous in the wrong client."}]}, {"type": "drug_card", "attrs": {"name": "Metoprolol / atenolol / propranolol / carvedilol", "drug_class": "Beta-adrenergic blocker", "fields": [{"label": "Indications", "value": "Hypertension, angina, post-MI, heart failure (carvedilol, metoprolol succinate), atrial fibrillation rate control, migraine prophylaxis"}, {"label": "Key effects", "value": "↓ heart rate, ↓ blood pressure, ↓ myocardial oxygen demand"}, {"label": "Side effects", "value": "Bradycardia, hypotension, fatigue, dizziness, impotence, masked hypoglycaemia"}, {"label": "Nursing considerations", "value": "Hold and reassess if apical pulse is below 60 or systolic BP below 90 — take the APICAL pulse for a full minute"}]}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The three exam traps"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "1. Masked hypoglycaemia in diabetes"}]}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "Beta blockers blunt tachycardia, tremor and palpitations — the early warning signs of a hypo. A diabetic client on a beta blocker may go straight to confusion. Teach them to check glucose rather than wait to feel it. Sweating is preserved."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "2. Non-selective agents and the airway"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Propranolol blocks beta-2 as well as beta-1, causing bronchoconstriction. In asthma or COPD a non-selective beta blocker is contraindicated; a cardioselective one (metoprolol, atenolol) is used with caution."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "3. Never stop abruptly"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Abrupt withdrawal causes rebound tachycardia, hypertension, and can precipitate angina or infarction. This is a teaching-point answer on almost every beta blocker question."}]}, {"type": "callout", "attrs": {"tone": "tip"}, "content": [{"type": "text", "text": "Teach the client to rise slowly — orthostatic hypotension is the most common reason these clients fall."}]}]}$body$::jsonb,
  tags = ARRAY['beta-blocker', 'hypertension', 'cardiac']::text[],
  pillars = ARRAY['Pharmacological and Parenteral Therapies']::text[],
  is_published = TRUE,
  version_id = gen_random_uuid(),
  updated_at = NOW()
WHERE note_id = 'e6e59935-4747-4669-9e8f-82bbaea90845'
  AND tutor_id = '4ed777d7-e4f7-403b-88f4-63ce5432d65e';

-- Furosemide (Lasix)
UPDATE nclex_tutor_library_notes SET
  title = 'Furosemide (Lasix)',
  subtitle = 'The loop diuretic, and the potassium problem',
  body = $body${"type": "doc", "content": [{"type": "drug_card", "attrs": {"name": "Furosemide (Lasix)", "drug_class": "Loop diuretic", "fields": [{"label": "Indications", "value": "Heart failure, pulmonary oedema, oedema of renal or hepatic origin, hypertension, hypercalcaemia"}, {"label": "Action", "value": "Blocks reabsorption in the ascending loop of Henle — powerful, rapid, and wastes potassium"}, {"label": "Side effects", "value": "Hypokalaemia, hyponatraemia, hypotension, dehydration, ototoxicity, hyperglycaemia, hyperuricaemia"}, {"label": "Nursing considerations", "value": "Daily weight is the most reliable measure of fluid loss; monitor potassium; give in the morning; push IV slowly"}]}}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "Hypokalaemia plus digoxin equals digoxin toxicity. If a client is on both furosemide and digoxin, potassium is the answer to most questions about them."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "What to monitor, in order of exam frequency"}]}, {"type": "lab_values", "attrs": {"title": "Monitoring priorities", "columns": [{"label": "Parameter"}, {"label": "Watch for"}, {"label": "Action"}], "rows": [["Serum potassium", "Below 3.5 mEq/L", "Hold, report, expect supplementation"], ["Daily weight", "1 kg = roughly 1 litre of fluid", "Same scale, same time, same clothing"], ["Blood pressure", "Orthostatic drop", "Rise slowly; hold if systolic below 90 per protocol"], ["Hearing", "Tinnitus, hearing loss", "Ototoxicity — worse with rapid IV push and with aminoglycosides"]]}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Teaching points"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Take it in the morning, so the diuresis does not interrupt sleep"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Eat potassium-rich foods — bananas, oranges, potatoes, spinach, avocado"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Report muscle weakness, cramps or an irregular heartbeat"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Change position slowly"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Weigh daily and report a gain of more than 1 kg in a day, or 2 kg in a week"}]}]}]}, {"type": "callout", "attrs": {"tone": "warning"}, "content": [{"type": "text", "text": "Furosemide is a sulfonamide derivative. A documented sulfa allergy is worth reporting before the first dose."}]}]}$body$::jsonb,
  tags = ARRAY['diuretic', 'fluid', 'high-yield']::text[],
  pillars = ARRAY['Pharmacological and Parenteral Therapies', 'Physiological Adaptation']::text[],
  is_published = TRUE,
  version_id = gen_random_uuid(),
  updated_at = NOW()
WHERE note_id = '65dafcf5-b54d-4cab-927d-2e8f7d929590'
  AND tutor_id = '4ed777d7-e4f7-403b-88f4-63ce5432d65e';

-- Insulin types and timing
UPDATE nclex_tutor_library_notes SET
  title = 'Insulin types and timing',
  subtitle = 'Onset, peak, duration — and when a hypo will actually happen',
  body = $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "The exam rarely asks what an insulin is. It asks "}, {"type": "text", "text": "when", "marks": [{"type": "bold"}]}, {"type": "text", "text": " the client is most likely to become hypoglycaemic — which is the peak."}]}, {"type": "lab_values", "attrs": {"title": "Insulin at a glance", "columns": [{"label": "Type"}, {"label": "Example"}, {"label": "Onset"}, {"label": "Peak"}, {"label": "Duration"}], "rows": [["Rapid-acting", "Lispro, aspart, glulisine", "10–30 min", "30 min – 3 h", "3–5 h"], ["Short-acting", "Regular", "30–60 min", "2–4 h", "5–8 h"], ["Intermediate", "NPH", "1–2 h", "4–12 h", "12–18 h"], ["Long-acting", "Glargine, detemir", "1–2 h", "No pronounced peak", "24 h"]]}}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "Rapid-acting insulin must be given with food ON THE TRAY, not merely ordered. Giving lispro and then finding the client is NPO for a procedure is a genuine harm event and a favourite exam scenario."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The rules that get tested"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Mixing"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Draw "}, {"type": "text", "text": "clear before cloudy", "marks": [{"type": "bold"}]}, {"type": "text", "text": " — regular insulin before NPH. Inject air into the NPH vial first, then air into the regular, then draw the regular. Contaminating the regular vial with NPH changes its action."}]}, {"type": "callout", "attrs": {"tone": "memory"}, "content": [{"type": "text", "text": "Clear before cloudy. RN — Regular before NPH."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "What can be given IV"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Only "}, {"type": "text", "text": "regular", "marks": [{"type": "bold"}]}, {"type": "text", "text": " insulin is given intravenously. Any question showing an insulin drip is showing regular insulin."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "What cannot be mixed"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Glargine and detemir are never mixed with anything, and never diluted."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Hypoglycaemia"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Below 70 mg/dL. Conscious and able to swallow: 15 grams of fast carbohydrate, recheck in 15 minutes, repeat if still low, then a protein-containing snack. Unconscious: IV dextrose 50%, or glucagon IM if no access."}]}, {"type": "callout", "attrs": {"tone": "memory"}, "content": [{"type": "text", "text": "The rule of 15 — 15 grams, wait 15 minutes, recheck."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Sick-day rules"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Never stop insulin because the client is not eating — illness raises glucose"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Check glucose every 3–4 hours"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Check urine or blood ketones"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Drink fluids to prevent dehydration"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Contact the provider for vomiting lasting more than 4 hours"}]}]}]}]}$body$::jsonb,
  tags = ARRAY['insulin', 'diabetes', 'high-yield']::text[],
  pillars = ARRAY['Pharmacological and Parenteral Therapies']::text[],
  is_published = TRUE,
  version_id = gen_random_uuid(),
  updated_at = NOW()
WHERE note_id = '110db939-3d55-4a1c-9252-d3af952a975b'
  AND tutor_id = '4ed777d7-e4f7-403b-88f4-63ce5432d65e';

-- Quick reference: lab values
UPDATE nclex_tutor_library_notes SET
  title = 'Quick reference: lab values',
  subtitle = 'The values worth memorising, and what each one changes',
  body = $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "You will not be given a reference range. These are the values the exam expects you to recognise on sight — and, more importantly, to act on."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Electrolytes"}]}, {"type": "lab_values", "attrs": {"title": "Electrolytes", "columns": [{"label": "Test"}, {"label": "Normal"}, {"label": "If high"}, {"label": "If low"}], "rows": [["Sodium", "135–145 mEq/L", "Thirst, dry mucosa, restlessness, seizures", "Confusion, headache, seizures — correct SLOWLY"], ["Potassium", "3.5–5.0 mEq/L", "Peaked T waves, muscle weakness, cardiac arrest", "Flat T waves, U waves, weakness, digoxin toxicity"], ["Calcium", "9.0–10.5 mg/dL", "Bone pain, stones, lethargy, constipation", "Tetany, Chvostek and Trousseau signs, laryngospasm"], ["Magnesium", "1.3–2.1 mEq/L", "Loss of deep tendon reflexes, respiratory depression", "Tremor, tetany, torsades de pointes"]]}}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "Potassium is never given IV push. Ever. It is always diluted and infused on a pump — IV push potassium is fatal."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Haematology and coagulation"}]}, {"type": "lab_values", "attrs": {"title": "Blood", "columns": [{"label": "Test"}, {"label": "Normal"}, {"label": "Notes"}], "rows": [["Haemoglobin", "12–18 g/dL", "Below 7 typically triggers transfusion"], ["Haematocrit", "37–52%", "Roughly three times the haemoglobin"], ["WBC", "5,000–10,000/mm³", "Below 1,000 neutrophils = neutropenic precautions"], ["Platelets", "150,000–400,000/mm³", "Below 50,000 = bleeding precautions; below 20,000 = spontaneous bleeding risk"], ["INR", "0.8–1.1 (2–3 on warfarin)", "Above 5 with bleeding is an emergency"]]}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Renal, glucose, cardiac"}]}, {"type": "lab_values", "attrs": {"title": "Other high-yield values", "columns": [{"label": "Test"}, {"label": "Normal"}, {"label": "Notes"}], "rows": [["BUN", "10–20 mg/dL", "Rises with dehydration as well as renal failure"], ["Creatinine", "0.6–1.2 mg/dL", "The more specific kidney marker"], ["Fasting glucose", "70–110 mg/dL", "Below 70 is hypoglycaemia"], ["HbA1c", "Below 6% (target under 7% in diabetes)", "Three-month average"], ["Digoxin", "0.5–2.0 ng/mL", "Toxicity: nausea, visual halos, bradycardia"], ["Lithium", "0.6–1.2 mEq/L", "Above 1.5 is toxic — a narrow window"]]}}, {"type": "callout", "attrs": {"tone": "tip"}, "content": [{"type": "text", "text": "Learn the drug levels — digoxin and lithium — before you learn anything else on this page. They are narrow, they are tested, and the answer is always to hold the drug and report."}]}]}$body$::jsonb,
  tags = ARRAY['lab', 'reference', 'cheat-sheet']::text[],
  pillars = ARRAY['Reduction of Risk Potential', 'Physiological Adaptation']::text[],
  is_published = TRUE,
  version_id = gen_random_uuid(),
  updated_at = NOW()
WHERE note_id = '6cd93a48-19d2-4f6c-9b82-275a6898996b'
  AND tutor_id = '4ed777d7-e4f7-403b-88f4-63ce5432d65e';

-- ABG interpretation
UPDATE nclex_tutor_library_notes SET
  title = 'ABG interpretation',
  subtitle = 'A method that works in under a minute',
  body = $body${"type": "doc", "content": [{"type": "lab_values", "attrs": {"title": "Normal values", "columns": [{"label": "Value"}, {"label": "Normal range"}], "rows": [["pH", "7.35–7.45"], ["PaCO₂", "35–45 mmHg"], ["HCO₃⁻", "22–26 mEq/L"], ["PaO₂", "80–100 mmHg"]]}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The method"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Look at the pH."}, {"type": "text", "text": " Below 7.35 acidosis, above 7.45 alkalosis."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Look at the CO₂."}, {"type": "text", "text": " If it moves in the OPPOSITE direction to the pH, the problem is respiratory."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Look at the bicarbonate."}, {"type": "text", "text": " If it moves in the SAME direction as the pH, the problem is metabolic."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Check compensation."}, {"type": "text", "text": " If the other value has also shifted, the body is compensating. pH back in range = fully compensated."}]}]}]}, {"type": "callout", "attrs": {"tone": "memory"}, "content": [{"type": "text", "text": "ROME — Respiratory Opposite, Metabolic Equal. CO₂ opposite to pH is respiratory; bicarbonate equal in direction to pH is metabolic."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Worked examples"}]}, {"type": "lab_values", "attrs": {"title": "Read these four", "columns": [{"label": "pH"}, {"label": "CO₂"}, {"label": "HCO₃"}, {"label": "Interpretation"}], "rows": [["7.28", "52", "24", "Respiratory acidosis, uncompensated"], ["7.50", "30", "23", "Respiratory alkalosis, uncompensated"], ["7.30", "38", "17", "Metabolic acidosis, uncompensated"], ["7.36", "50", "29", "Respiratory acidosis, fully compensated"]]}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "What causes what"}]}, {"type": "lab_values", "attrs": {"title": "Causes", "columns": [{"label": "Disorder"}, {"label": "Common causes"}], "rows": [["Respiratory acidosis", "Hypoventilation — COPD, oversedation, opioid overdose, chest trauma, atelectasis"], ["Respiratory alkalosis", "Hyperventilation — anxiety, pain, fever, high altitude, early sepsis"], ["Metabolic acidosis", "Diabetic ketoacidosis, renal failure, severe diarrhoea, shock, salicylate overdose"], ["Metabolic alkalosis", "Vomiting, gastric suction, excess antacids, diuretics"]]}}, {"type": "callout", "attrs": {"tone": "warning"}, "content": [{"type": "text", "text": "Prolonged vomiting or continuous nasogastric suction loses hydrogen ions and chloride — metabolic alkalosis. Severe diarrhoea loses bicarbonate — metabolic acidosis. The exam tests this pair directly."}]}]}$body$::jsonb,
  tags = ARRAY['abg', 'high-yield']::text[],
  pillars = ARRAY['Reduction of Risk Potential', 'Physiological Adaptation']::text[],
  is_published = TRUE,
  version_id = gen_random_uuid(),
  updated_at = NOW()
WHERE note_id = '1c71d58f-ca5c-48de-877b-e04d4ec9b763'
  AND tutor_id = '4ed777d7-e4f7-403b-88f4-63ce5432d65e';

-- Common cardiac rhythms
UPDATE nclex_tutor_library_notes SET
  title = 'Common cardiac rhythms',
  subtitle = 'The six strips the exam expects you to name and act on',
  body = $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "You are not being asked to be a cardiologist. You are being asked: is this rhythm perfusing, and what do I do first?"}]}, {"type": "lab_values", "attrs": {"title": "The six", "columns": [{"label": "Rhythm"}, {"label": "Recognise by"}, {"label": "First action"}], "rows": [["Normal sinus", "Rate 60–100, P before every QRS, regular", "None"], ["Sinus bradycardia", "Rate below 60, otherwise normal", "Assess symptoms; atropine if symptomatic"], ["Sinus tachycardia", "Rate above 100, otherwise normal", "Treat the CAUSE — fever, pain, hypovolaemia, anxiety"], ["Atrial fibrillation", "Irregularly irregular, no discernible P waves", "Rate control and anticoagulation — stroke risk"], ["Ventricular tachycardia", "Wide, bizarre QRS, rapid", "Check a PULSE. Pulse: antiarrhythmic. No pulse: defibrillate"], ["Ventricular fibrillation", "Chaotic, no identifiable complexes", "CPR and DEFIBRILLATE immediately"]]}}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "The one decision that matters in ventricular tachycardia is whether there is a pulse. Pulseless VT is defibrillated exactly like VF. A question that gives you VT and does not mention a pulse is asking you to check for one."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Asystole is not shocked"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A flat line is not a shockable rhythm. CPR and epinephrine. Confirm asystole in more than one lead — a disconnected lead looks identical."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The order in a witnessed arrest"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Check responsiveness and call for help"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Start compressions — C before A and B"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Attach the defibrillator or AED"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Shock if the rhythm is VF or pulseless VT"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Resume compressions immediately after the shock"}]}]}]}, {"type": "callout", "attrs": {"tone": "tip"}, "content": [{"type": "text", "text": "Every rhythm question is really \"is the client perfusing?\" Pulse, blood pressure, level of consciousness. A rhythm on a monitor with no client assessment is the wrong answer waiting to happen."}]}]}$body$::jsonb,
  tags = ARRAY['cardiac', 'rhythm', 'high-yield']::text[],
  pillars = ARRAY['Physiological Adaptation', 'Reduction of Risk Potential']::text[],
  is_published = TRUE,
  version_id = gen_random_uuid(),
  updated_at = NOW()
WHERE note_id = 'f5549c74-ac42-4e50-87b8-f520222a6f2e'
  AND tutor_id = '4ed777d7-e4f7-403b-88f4-63ce5432d65e';

-- Normal Sinus Rhythm (NSR)
UPDATE nclex_tutor_library_notes SET
  title = 'Normal Sinus Rhythm (NSR)',
  subtitle = 'The baseline every other strip is measured against',
  body = $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "You cannot recognise an abnormal rhythm until normal is automatic."}]}, {"type": "lab_values", "attrs": {"title": "The five criteria", "columns": [{"label": "Feature"}, {"label": "Normal sinus rhythm"}], "rows": [["Rate", "60–100 beats per minute"], ["Rhythm", "Regular — R-R intervals equal"], ["P wave", "One upright P before every QRS, all the same shape"], ["PR interval", "0.12–0.20 seconds (3–5 small squares)"], ["QRS", "Under 0.12 seconds (under 3 small squares)"]]}}, {"type": "callout", "attrs": {"tone": "memory"}, "content": [{"type": "text", "text": "Every P has a QRS, every QRS has a P, and the spacing never changes. Break any one of those and you have a named arrhythmia."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "What each variation is called"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Same criteria, rate under 60 — sinus bradycardia"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Same criteria, rate over 100 — sinus tachycardia"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Rate varies with breathing, otherwise normal — sinus arrhythmia, normal in children and young adults"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "PR interval over 0.20 seconds, constant — first-degree AV block"}]}]}]}, {"type": "callout", "attrs": {"tone": "tip"}, "content": [{"type": "text", "text": "Count rate fast: number of QRS complexes in a 6-second strip × 10."}]}]}$body$::jsonb,
  tags = ARRAY['nsr', 'cardiac']::text[],
  pillars = ARRAY['Physiological Adaptation']::text[],
  is_published = TRUE,
  version_id = gen_random_uuid(),
  updated_at = NOW()
WHERE note_id = '781b24a9-552c-4440-ae1e-7086d6a06fc7'
  AND tutor_id = '4ed777d7-e4f7-403b-88f4-63ce5432d65e';

-- Atrial Fibrillation (AF)
UPDATE nclex_tutor_library_notes SET
  title = 'Atrial Fibrillation (AF)',
  subtitle = 'Irregularly irregular — and why the real danger is stroke',
  body = $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Atrial fibrillation is disorganised atrial activity. The atria quiver instead of contracting, so blood pools — and pooled blood clots."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Recognise it"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Irregularly irregular rhythm — no pattern at all to the R-R intervals"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "No identifiable P waves; a wavy, chaotic baseline"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "QRS usually normal in width"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Apical rate often faster than the radial — a pulse deficit"}]}]}]}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "The client loses the atrial kick — up to 30% of cardiac output. That is why a client in new AF can drop their blood pressure suddenly."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The three treatment goals"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Rate control"}, {"type": "text", "text": " — beta blockers, diltiazem, digoxin"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Rhythm control"}, {"type": "text", "text": " — amiodarone, or cardioversion"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Anticoagulation"}, {"type": "text", "text": " — warfarin or a direct oral anticoagulant; this is the one that prevents the stroke"}]}]}]}, {"type": "callout", "attrs": {"tone": "warning"}, "content": [{"type": "text", "text": "Elective cardioversion of AF lasting more than 48 hours requires anticoagulation FIRST, or 3 weeks of it, because converting to sinus rhythm can launch an existing clot. This is a heavily tested point."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "What to teach"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Take the pulse daily and report a rate over 100 or under 60"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Report sudden weakness on one side, facial droop or slurred speech immediately — these are stroke symptoms"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Keep INR appointments if on warfarin"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Limit caffeine and alcohol — both trigger episodes"}]}]}]}]}$body$::jsonb,
  tags = ARRAY['cardiac', 'af', 'high-yield']::text[],
  pillars = ARRAY['Physiological Adaptation', 'Reduction of Risk Potential']::text[],
  is_published = TRUE,
  version_id = gen_random_uuid(),
  updated_at = NOW()
WHERE note_id = '745be3c4-1000-4a4e-bc61-932b8303628b'
  AND tutor_id = '4ed777d7-e4f7-403b-88f4-63ce5432d65e';

-- Asthma vs COPD
UPDATE nclex_tutor_library_notes SET
  title = 'Asthma vs COPD',
  subtitle = 'Two obstructive diseases the exam deliberately confuses',
  body = $body${"type": "doc", "content": [{"type": "lab_values", "attrs": {"title": "The distinction", "columns": [{"label": ""}, {"label": "Asthma"}, {"label": "COPD"}], "rows": [["Nature", "Reversible bronchospasm", "Largely irreversible airflow limitation"], ["Typical age", "Often childhood onset", "Usually over 40, smoking history"], ["Pattern", "Episodic — well between attacks", "Progressive, daily"], ["Classic sign", "Expiratory wheeze, chest tightness", "Barrel chest, pursed-lip breathing, clubbing"], ["Oxygen target", "Normal saturation", "88–92% — deliberately lower"]]}}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "High-flow oxygen in COPD can suppress the hypoxic drive and cause respiratory depression. Titrate to 88–92%. This does NOT mean withholding oxygen from a hypoxic client — it means not over-oxygenating."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The asthma trap"}]}, {"type": "callout", "attrs": {"tone": "warning"}, "content": [{"type": "text", "text": "A SILENT CHEST in asthma is not improvement — it is a chest too tight to move air. It is an emergency. A wheeze that disappears while the client looks worse means deterioration."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Inhaler order"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Bronchodilator first, then the steroid, waiting 1–5 minutes between them. The bronchodilator opens the airway so the steroid reaches further in."}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Rinse the mouth after any inhaled corticosteroid — prevents oral candidiasis"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Salbutamol/albuterol is the RESCUE inhaler — carried at all times"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Increasing rescue-inhaler use is a sign of worsening control, and a reason to review, not to keep going"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Positioning"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "High Fowler's or tripod — sitting up, leaning forward, arms braced. Pursed-lip breathing prolongs expiration and keeps small airways open in COPD."}]}]}$body$::jsonb,
  tags = ARRAY['respiratory', 'chronic']::text[],
  pillars = ARRAY['Physiological Adaptation']::text[],
  is_published = TRUE,
  version_id = gen_random_uuid(),
  updated_at = NOW()
WHERE note_id = 'ed1308d0-0ffe-4ca5-ae4b-54c312e77a39'
  AND tutor_id = '4ed777d7-e4f7-403b-88f4-63ce5432d65e';

-- Hypoglycemia vs hyperglycemia
UPDATE nclex_tutor_library_notes SET
  title = 'Hypoglycemia vs hyperglycemia',
  subtitle = 'Fast and cold, or slow and hot',
  body = $body${"type": "doc", "content": [{"type": "lab_values", "attrs": {"title": "Telling them apart", "columns": [{"label": ""}, {"label": "Hypoglycaemia"}, {"label": "Hyperglycaemia"}], "rows": [["Onset", "Sudden — minutes", "Gradual — hours to days"], ["Skin", "Cold, clammy, sweating", "Warm, dry, flushed"], ["Mental state", "Shaky, irritable, confused, may look drunk", "Lethargic, drowsy, progressing to coma"], ["Breathing", "Normal", "Kussmaul — deep and rapid (in DKA)"], ["Other", "Hunger, tremor, tachycardia, headache", "Thirst, polyuria, fruity breath, dehydration"], ["Glucose", "Below 70 mg/dL", "Above 250 mg/dL (DKA), often far higher in HHS"]]}}, {"type": "callout", "attrs": {"tone": "memory"}, "content": [{"type": "text", "text": "Cold and clammy, need some candy. Hot and dry, sugar high."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Treating hypoglycaemia"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Conscious and able to swallow: 15 grams of fast carbohydrate — 120 mL fruit juice, 3 glucose tablets, 1 tablespoon of honey. Wait 15 minutes, recheck, repeat if still below 70. Then give a snack with protein."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Unconscious or unable to swallow: nothing by mouth. IV dextrose 50%, or glucagon IM if there is no IV access."}]}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "Never put food or fluid in the mouth of a client who is not fully awake. Aspiration turns a treatable hypo into pneumonia."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "DKA versus HHS"}]}, {"type": "lab_values", "attrs": {"title": "The two hyperglycaemic emergencies", "columns": [{"label": ""}, {"label": "DKA"}, {"label": "HHS"}], "rows": [["Usually", "Type 1", "Type 2"], ["Glucose", "Above 250 mg/dL", "Often above 600 mg/dL"], ["Ketones", "Present", "Absent or minimal"], ["pH", "Acidotic, below 7.35", "Normal"], ["Hallmark", "Kussmaul breathing, fruity breath", "Profound dehydration, neurological changes"]]}}, {"type": "paragraph", "content": [{"type": "text", "text": "Both are treated with fluids first, then insulin, then potassium replacement — because insulin drives potassium into cells and can cause a dangerous fall."}]}]}$body$::jsonb,
  tags = ARRAY['diabetes', 'emergency', 'high-yield']::text[],
  pillars = ARRAY['Physiological Adaptation', 'Pharmacological and Parenteral Therapies']::text[],
  is_published = TRUE,
  version_id = gen_random_uuid(),
  updated_at = NOW()
WHERE note_id = '0de5f48a-25ba-462d-8f8a-cad8f8534a89'
  AND tutor_id = '4ed777d7-e4f7-403b-88f4-63ce5432d65e';

-- Thyroid disorders snapshot
UPDATE nclex_tutor_library_notes SET
  title = 'Thyroid disorders snapshot',
  subtitle = 'Everything speeds up, or everything slows down',
  body = $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Thyroid questions are easy marks once you accept the single organising idea: the thyroid sets the body's metabolic speed."}]}, {"type": "lab_values", "attrs": {"title": "Hyper versus hypo", "columns": [{"label": ""}, {"label": "Hyperthyroidism (Graves)"}, {"label": "Hypothyroidism (Hashimoto)"}], "rows": [["Weight", "Loss despite eating more", "Gain despite eating less"], ["Temperature", "Heat intolerance, sweating", "Cold intolerance"], ["Heart", "Tachycardia, palpitations, AF", "Bradycardia"], ["Bowel", "Diarrhoea", "Constipation"], ["Mood", "Anxious, restless, insomnia", "Depressed, lethargic, slow speech"], ["Distinctive", "Exophthalmos, goitre", "Dry skin, coarse hair, puffy face"]]}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The two crises"}]}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "THYROID STORM — fever above 38.5°C, tachycardia, agitation, delirium. Often triggered by infection or by surgery on an unprepared client. Cooling, beta blockers, antithyroid drugs. Life-threatening."}]}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "MYXOEDEMA COMA — hypothermia, hypotension, hypoventilation, unresponsive. Warm the client passively, support the airway, IV thyroid hormone."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Levothyroxine teaching"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Take in the MORNING on an empty stomach, 30–60 minutes before food"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "It is lifelong — do not stop when feeling well"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Report chest pain, palpitations or a resting pulse above 100 — the dose may be too high"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Separate from calcium and iron by 4 hours — they block absorption"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "After a thyroidectomy"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Keep a tracheostomy set at the bedside. Watch for airway obstruction from swelling, for haemorrhage (check BEHIND the neck — blood pools there), and for hypocalcaemic tetany if the parathyroids were disturbed — test for Chvostek and Trousseau signs."}]}]}$body$::jsonb,
  tags = ARRAY['thyroid', 'endocrine']::text[],
  pillars = ARRAY['Physiological Adaptation']::text[],
  is_published = TRUE,
  version_id = gen_random_uuid(),
  updated_at = NOW()
WHERE note_id = 'c9563362-f831-4a17-ae67-68313010ad35'
  AND tutor_id = '4ed777d7-e4f7-403b-88f4-63ce5432d65e';

-- Stages of labor
UPDATE nclex_tutor_library_notes SET
  title = 'Stages of labor',
  subtitle = 'What changes, and what the nurse does in each',
  body = $body${"type": "doc", "content": [{"type": "lab_values", "attrs": {"title": "The four stages", "columns": [{"label": "Stage"}, {"label": "Definition"}, {"label": "Nursing priority"}], "rows": [["First — latent", "0–5 cm, contractions mild, 5–30 min apart", "Encourage walking, light food, orient to unit"], ["First — active", "6–10 cm, contractions 2–5 min apart, strong", "Monitor fetal heart rate, pain relief, position changes"], ["Second", "Full dilation to birth", "Coach pushing, monitor FHR with every contraction"], ["Third", "Birth of baby to delivery of placenta", "Watch for the gush of blood, cord lengthening, uterus rising"], ["Fourth", "First 1–4 hours after delivery", "Fundus, lochia, bladder, vital signs every 15 minutes"]]}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Fetal heart rate — the decelerations"}]}, {"type": "callout", "attrs": {"tone": "memory"}, "content": [{"type": "text", "text": "VEAL CHOP. Variable→Cord compression. Early→Head compression. Accelerations→OK. Late→Placental insufficiency."}]}, {"type": "lab_values", "attrs": {"title": "What to do", "columns": [{"label": "Pattern"}, {"label": "Cause"}, {"label": "Action"}], "rows": [["Early deceleration", "Head compression", "None — benign"], ["Variable deceleration", "Cord compression", "Reposition, then amnioinfusion if ordered"], ["Late deceleration", "Uteroplacental insufficiency", "Left side, oxygen, stop oxytocin, IV fluids, call provider"], ["Acceleration", "Fetal movement", "Reassuring"]]}}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "Late decelerations are the ominous one. Turn the client to the LEFT side first — it takes the uterus off the vena cava and restores placental perfusion immediately."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Cord prolapse"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "If the cord is visible or palpable: call for help, and with a gloved hand push the presenting part OFF the cord. Place the client in knee-chest or Trendelenburg. Do not push the cord back in. Do not leave the client."}]}]}$body$::jsonb,
  tags = ARRAY['labor', 'ob', 'high-yield']::text[],
  pillars = ARRAY['Health Promotion and Maintenance']::text[],
  is_published = TRUE,
  version_id = gen_random_uuid(),
  updated_at = NOW()
WHERE note_id = 'fe256643-9d75-4c17-b8f6-59ab4948666b'
  AND tutor_id = '4ed777d7-e4f7-403b-88f4-63ce5432d65e';

-- Postpartum hemorrhage
UPDATE nclex_tutor_library_notes SET
  title = 'Postpartum hemorrhage',
  subtitle = 'The leading cause of maternal death — and the first thing you do',
  body = $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Defined as blood loss over 500 mL after a vaginal birth, or over 1000 mL after a caesarean. The most common cause, by a wide margin, is "}, {"type": "text", "text": "uterine atony", "marks": [{"type": "bold"}]}, {"type": "text", "text": " — a uterus that will not contract."}]}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "FIRST ACTION for a boggy uterus is to MASSAGE THE FUNDUS. Not call the provider, not start an IV, not give a drug. Massage first — a contracted uterus clamps its own bleeding vessels."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The four Ts"}]}, {"type": "lab_values", "attrs": {"title": "Causes", "columns": [{"label": "Cause"}, {"label": "Recognise by"}, {"label": "Management"}], "rows": [["Tone — uterine atony", "Boggy, soft, high fundus", "Massage; oxytocin; empty the bladder"], ["Trauma", "Firm fundus but steady bright-red bleeding", "Inspect for laceration or haematoma"], ["Tissue", "Retained placental fragments", "Removal; ultrasound"], ["Thrombin", "Coagulopathy, oozing from sites", "Correct clotting factors"]]}}, {"type": "callout", "attrs": {"tone": "tip"}, "content": [{"type": "text", "text": "A FIRM fundus with continued bleeding is the discriminator — that is not atony, so stop massaging and start looking for a tear."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Assessment"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Fundus — firm or boggy, at/above/below the umbilicus, midline or deviated"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A fundus deviated to the right usually means a FULL BLADDER — have the client void, then reassess"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Lochia — count and weigh pads; 1 gram equals 1 mL"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Vital signs — tachycardia comes before hypotension in a young woman; do not wait for the blood pressure to fall"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Drugs"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Oxytocin"}, {"type": "text", "text": " — first line"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Methylergonovine"}, {"type": "text", "text": " — contraindicated in HYPERTENSION"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Carboprost"}, {"type": "text", "text": " — contraindicated in ASTHMA"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Misoprostol"}, {"type": "text", "text": " — rectal or sublingual"}]}]}]}, {"type": "callout", "attrs": {"tone": "warning"}, "content": [{"type": "text", "text": "Those two contraindications are tested almost every time these drugs appear. Methylergonovine raises blood pressure; carboprost causes bronchospasm."}]}]}$body$::jsonb,
  tags = ARRAY['ob', 'emergency', 'high-yield']::text[],
  pillars = ARRAY['Health Promotion and Maintenance', 'Physiological Adaptation']::text[],
  is_published = TRUE,
  version_id = gen_random_uuid(),
  updated_at = NOW()
WHERE note_id = '2f7ca1e3-9262-48ee-b37d-aa42b00e641c'
  AND tutor_id = '4ed777d7-e4f7-403b-88f4-63ce5432d65e';

-- Newborn APGAR scoring
UPDATE nclex_tutor_library_notes SET
  title = 'Newborn APGAR scoring',
  subtitle = 'Five signs, scored twice',
  body = $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Scored at "}, {"type": "text", "text": "1 minute", "marks": [{"type": "bold"}]}, {"type": "text", "text": " and "}, {"type": "text", "text": "5 minutes", "marks": [{"type": "bold"}]}, {"type": "text", "text": " after birth. Each of the five signs scores 0, 1 or 2, for a maximum of 10."}]}, {"type": "lab_values", "attrs": {"title": "The five signs", "columns": [{"label": "Sign"}, {"label": "0"}, {"label": "1"}, {"label": "2"}], "rows": [["Appearance (colour)", "Blue or pale", "Body pink, extremities blue", "Completely pink"], ["Pulse", "Absent", "Below 100", "Above 100"], ["Grimace (reflex)", "No response", "Grimace", "Cry, cough, sneeze"], ["Activity (tone)", "Limp", "Some flexion", "Active motion"], ["Respiration", "Absent", "Slow, irregular, weak cry", "Good, strong cry"]]}}, {"type": "callout", "attrs": {"tone": "memory"}, "content": [{"type": "text", "text": "APGAR — Appearance, Pulse, Grimace, Activity, Respiration."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Interpreting the score"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "7–10"}, {"type": "text", "text": " — good condition, routine care"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "4–6"}, {"type": "text", "text": " — moderately depressed, needs stimulation and oxygen"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "0–3"}, {"type": "text", "text": " — severely depressed, resuscitate immediately"}]}]}]}, {"type": "callout", "attrs": {"tone": "warning"}, "content": [{"type": "text", "text": "Acrocyanosis — blue hands and feet with a pink body — is NORMAL in the first 24 hours and scores 1, not 0. Central cyanosis of the trunk or lips is never normal."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "What APGAR is not"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "It does not predict long-term outcome and it is not used to decide whether to start resuscitation. Resuscitation begins on assessment, not on waiting for a score at one minute."}]}]}$body$::jsonb,
  tags = ARRAY['peds', 'newborn', 'assessment']::text[],
  pillars = ARRAY['Health Promotion and Maintenance']::text[],
  is_published = TRUE,
  version_id = gen_random_uuid(),
  updated_at = NOW()
WHERE note_id = 'b995611a-d64d-4f9b-9990-bc833482317b'
  AND tutor_id = '4ed777d7-e4f7-403b-88f4-63ce5432d65e';

-- Pediatric vital signs by age
UPDATE nclex_tutor_library_notes SET
  title = 'Pediatric vital signs by age',
  subtitle = 'Normal ranges, and the sign that matters most in children',
  body = $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "The younger the child, the faster the heart and the faster the breathing. Blood pressure rises with age."}]}, {"type": "lab_values", "attrs": {"title": "Normal ranges", "columns": [{"label": "Age"}, {"label": "Heart rate"}, {"label": "Respiratory rate"}, {"label": "Systolic BP"}], "rows": [["Newborn", "100–160", "30–60", "60–90"], ["Infant (1–12 months)", "100–150", "25–40", "70–100"], ["Toddler (1–3 y)", "90–140", "20–30", "80–110"], ["Preschool (3–5 y)", "80–120", "20–25", "85–115"], ["School age (6–12 y)", "70–110", "18–25", "90–120"], ["Adolescent", "60–100", "12–20", "100–130"]]}}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "In a child, a falling blood pressure is a LATE sign of shock. Children compensate with tachycardia for a long time and then decompensate suddenly. Tachycardia plus poor perfusion is your warning — do not wait for hypotension."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Other paediatric red flags"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Bradycardia in a child is usually caused by HYPOXIA — open the airway and oxygenate before anything else"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Grunting, nasal flaring, retractions and head bobbing all indicate respiratory distress"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A quiet, floppy child who has stopped fighting you is deteriorating, not settling"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Assessment order"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Least invasive first. Respirations and heart rate before touching, then temperature and blood pressure last. Count respirations for a full minute in infants — they are normally irregular."}]}]}$body$::jsonb,
  tags = ARRAY['peds', 'assessment']::text[],
  pillars = ARRAY['Health Promotion and Maintenance']::text[],
  is_published = TRUE,
  version_id = gen_random_uuid(),
  updated_at = NOW()
WHERE note_id = 'e004d0eb-ce1d-42d0-b906-b9f254dba04b'
  AND tutor_id = '4ed777d7-e4f7-403b-88f4-63ce5432d65e';

-- Vaccination schedule essentials
UPDATE nclex_tutor_library_notes SET
  title = 'Vaccination schedule essentials',
  subtitle = 'What is due when, and who must not have a live vaccine',
  body = $body${"type": "doc", "content": [{"type": "lab_values", "attrs": {"title": "Routine childhood schedule", "columns": [{"label": "Age"}, {"label": "Vaccines due"}], "rows": [["Birth", "Hepatitis B (first dose)"], ["2 months", "DTaP, IPV, Hib, PCV, rotavirus, hepatitis B"], ["4 months", "DTaP, IPV, Hib, PCV, rotavirus"], ["6 months", "DTaP, Hib, PCV, rotavirus, hepatitis B, annual influenza"], ["12–15 months", "MMR, varicella, Hib, PCV, hepatitis A"], ["4–6 years", "DTaP, IPV, MMR, varicella"], ["11–12 years", "Tdap, HPV, meningococcal"]]}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Live vaccines — the ones with rules"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "MMR, varicella, rotavirus, and the intranasal influenza vaccine are live."}]}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "Live vaccines are contraindicated in pregnancy, in immunosuppression, and in clients on high-dose steroids or chemotherapy. This is the most commonly tested point in the topic."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "What is NOT a contraindication"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A mild illness with or without a low-grade fever"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Current antibiotic therapy"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Prematurity — vaccinate by chronological age"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Breastfeeding"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A family history of adverse reactions"}]}]}]}, {"type": "callout", "attrs": {"tone": "warning"}, "content": [{"type": "text", "text": "A true anaphylactic reaction to a previous dose or to a vaccine component IS a contraindication. Egg allergy is no longer a barrier to influenza vaccination in most guidance — soreness and low fever are expected effects, not allergy."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Teaching parents"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Expect soreness, redness and a low-grade fever for 24–48 hours"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Give paracetamol/acetaminophen for comfort — not aspirin, ever, in children"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Apply a cool compress to the injection site"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Return immediately for difficulty breathing, swelling of the face, or a high fever"}]}]}]}]}$body$::jsonb,
  tags = ARRAY['peds', 'immunization']::text[],
  pillars = ARRAY['Health Promotion and Maintenance', 'Safety and Infection Control']::text[],
  is_published = TRUE,
  version_id = gen_random_uuid(),
  updated_at = NOW()
WHERE note_id = '791ae0df-93c2-4cd4-a101-8678529011e6'
  AND tutor_id = '4ed777d7-e4f7-403b-88f4-63ce5432d65e';

-- Therapeutic communication techniques
UPDATE nclex_tutor_library_notes SET
  title = 'Therapeutic communication techniques',
  subtitle = 'How to spot the right answer when every option sounds kind',
  body = $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Communication questions are the ones candidates most often get wrong while feeling confident, because several options sound caring. The exam is not testing kindness. It is testing whether you keep the client talking."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Techniques that are usually right"}]}, {"type": "lab_values", "attrs": {"title": "Use these", "columns": [{"label": "Technique"}, {"label": "Sounds like"}], "rows": [["Open-ended question", "\"Tell me more about that.\""], ["Reflecting", "\"You sound frightened.\""], ["Restating", "\"You are saying the pain got worse overnight?\""], ["Silence", "Waiting, without filling the gap"], ["Offering self", "\"I will sit with you for a while.\""], ["Seeking clarification", "\"I am not sure I follow — can you explain?\""], ["Making an observation", "\"I notice you have not eaten today.\""]]}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Responses that are almost always wrong"}]}, {"type": "lab_values", "attrs": {"title": "Avoid these", "columns": [{"label": "Blocker"}, {"label": "Sounds like"}, {"label": "Why it is wrong"}], "rows": [["False reassurance", "\"Don't worry, it will be fine.\"", "Closes the conversation and may be untrue"], ["Giving advice", "\"If I were you, I would…\"", "Removes the client's autonomy"], ["Asking why", "\"Why did you do that?\"", "Demands justification, feels like blame"], ["Changing the subject", "\"Let's talk about your discharge.\"", "Abandons the client's concern"], ["Defending", "\"The nurses here are very good.\"", "Sides with staff against the client"], ["Closed question", "\"Are you feeling sad?\"", "Invites yes or no and stops there"]]}}, {"type": "callout", "attrs": {"tone": "memory"}, "content": [{"type": "text", "text": "The right answer usually lets the client speak next. If the option ends the conversation, it is probably wrong."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The tie-breaker"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "When two options both look therapeutic, choose the one that stays with the client's "}, {"type": "text", "text": "feeling", "marks": [{"type": "bold"}]}, {"type": "text", "text": " rather than the facts. \"You seem angry about the delay\" beats \"The doctor was held up in theatre\", even though the second is true and helpful."}]}, {"type": "callout", "attrs": {"tone": "warning"}, "content": [{"type": "text", "text": "Never agree to keep a secret, and never promise confidentiality you cannot deliver — particularly around self-harm."}]}]}$body$::jsonb,
  tags = ARRAY['communication', 'mental-health', 'high-yield']::text[],
  pillars = ARRAY['Psychosocial Integrity']::text[],
  is_published = TRUE,
  version_id = gen_random_uuid(),
  updated_at = NOW()
WHERE note_id = 'a46651cf-a07c-4cd3-aaae-e2b2b46936c4'
  AND tutor_id = '4ed777d7-e4f7-403b-88f4-63ce5432d65e';

-- Suicide risk assessment
UPDATE nclex_tutor_library_notes SET
  title = 'Suicide risk assessment',
  subtitle = 'Ask directly, then decide the level of observation',
  body = $body${"type": "doc", "content": [{"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "Asking a client directly whether they are thinking of killing themselves does NOT plant the idea. It is the single most important assessment action, and on the exam it is almost always the correct first step."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "What raises risk"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A specific plan"}, {"type": "text", "text": " — the more detailed and the more available the means, the higher the risk"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A previous attempt"}, {"type": "text", "text": " — the strongest single predictor"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Giving away possessions, putting affairs in order, saying goodbye"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sudden calm after a period of severe depression — often means the decision is made"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Male sex, older age, living alone, recent loss, substance use, chronic pain"}]}]}]}, {"type": "callout", "attrs": {"tone": "warning"}, "content": [{"type": "text", "text": "The most dangerous window is when a severely depressed client BEGINS to improve — energy returns before mood does, and they now have the capacity to act. Observation should increase, not relax."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Assessment sequence"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ask about thoughts — \"Are you thinking of harming yourself?\""}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ask about a plan — \"Have you thought about how?\""}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ask about means — \"Do you have access to that?\""}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ask about intent and timing"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Establish a level of observation and remove the means"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Nursing actions"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Place the client where they can be observed — near the nurses' station, not at the end of a corridor"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "One-to-one continuous observation for active intent, including in the bathroom"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Remove belts, cords, shoelaces, glass, razors, and check belongings"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Do NOT leave the client alone, including to fetch help — call out instead"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Document the client's own words verbatim"}]}]}]}, {"type": "callout", "attrs": {"tone": "tip"}, "content": [{"type": "text", "text": "A no-suicide contract is not a safety intervention and does not replace observation. If it appears as an option alongside direct assessment or removing means, it is the wrong answer."}]}]}$body$::jsonb,
  tags = ARRAY['mental-health', 'safety', 'high-yield']::text[],
  pillars = ARRAY['Psychosocial Integrity', 'Safety and Infection Control']::text[],
  is_published = TRUE,
  version_id = gen_random_uuid(),
  updated_at = NOW()
WHERE note_id = 'e2c39634-3596-4c34-bcc9-1359a48bc863'
  AND tutor_id = '4ed777d7-e4f7-403b-88f4-63ce5432d65e';

-- Your last two weeks
INSERT INTO nclex_tutor_library_notes
  (note_id, tutor_id, title, subtitle, body, tags, pillars,
   is_published, visibility_mode)
VALUES (
  '55000000-0000-4000-8000-000000000005', '4ed777d7-e4f7-403b-88f4-63ce5432d65e',
  'Your last two weeks',
  'A readiness plan for the fortnight before test day',
  $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "The last fortnight is not for learning new content. It is for consolidating what you have, fixing your timing, and removing every avoidable surprise on the day."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Fourteen days out"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sit one full-length timed mock under real conditions — no phone, no pauses"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Review every wrong answer and write the REASON, not the fact"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Rank your weakest three categories and give them your mornings"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Seven days out"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Switch from new content to review of your own error log"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Do 75 questions a day, mixed, timed"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Confirm your test centre, your route and your travel time"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Move your sleep to match your exam start time"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The day before"}]}, {"type": "callout", "attrs": {"tone": "tip"}, "content": [{"type": "text", "text": "Stop studying by early afternoon. There is no evidence that late cramming helps, and strong evidence that lost sleep hurts. Pack, eat, rest."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "What to bring"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Your Authorization to Test — the name on it must match your ID EXACTLY"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "One acceptable, current, signed photo ID — passport for international candidates"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Nothing else. No phone, no watch, no notes — everything goes in a locker"}]}]}]}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "A mismatch between the name on your ID and the name on your Authorization to Test will end your appointment at the door, and the fee is not refunded. Check it the week before, not on the morning."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "On the day"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Arrive 30 minutes early — arriving late usually means forfeiting the appointment"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Expect fingerprinting, a photograph and a palm scan; expect to be scanned again after every break"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Take the optional breaks even if you feel fine — the clock keeps running, but your concentration will not"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Expect questions you have never seen. Some are unscored trial items. Answer and move on"}]}]}]}, {"type": "callout", "attrs": {"tone": "memory"}, "content": [{"type": "text", "text": "You cannot skip and you cannot go back. Give every question your best reasoning once, then leave it behind — carrying question 12 into question 40 costs you both."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Afterwards"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Results timing varies by jurisdiction; some boards offer an unofficial result after 48 hours. Do not read anything into the number of questions you were given — see the note on how the exam decides."}]}]}$body$::jsonb,
  ARRAY['exam-strategy', 'test-day', 'high-yield']::text[],
  ARRAY['Management of Care']::text[],
  TRUE, 'TUTOR_WIDE'
)
ON CONFLICT (note_id) DO UPDATE SET
  title = EXCLUDED.title, subtitle = EXCLUDED.subtitle,
  body = EXCLUDED.body, tags = EXCLUDED.tags,
  pillars = EXCLUDED.pillars, is_published = TRUE,
  version_id = gen_random_uuid(), updated_at = NOW();

COMMIT;
